<template>

      <!-- <div v-if="loading_spinner" v-html="tableShimmer()"></div> -->
     

    <div class="modal fade" id="grnModal" tabindex="-1" role="dialog" aria-labelledby="editModalLabel" aria-hidden="true">
    <div class="modal-dialog modal-fullscreen modal-dialog-scrollable" role="document"> <!-- Changed to modal-xl and added scrollable -->
        <div class="modal-content"> <!-- Added min-height -->
            <div class="modal-header">
                <h5 class="modal-title" id="editModalLabel">GOOD RECEIVED NOTE # {{ grn?.id }}</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
            </div>
            <div class="modal-body">
             <span v-if="loading_spinner" v-html="tableShimmer()"></span>
  <div v-else>


      <div class="row layout-top-spacing">
        <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
          <div class="panel p-0">
            <div  class="custom-table table3 table-responsive">
              <table class="table table-bordered table-striped">
                <thead>
                  <tr>
                    <th>GRN No</th>
                    <th>LPO No</th>
                    <th>Requester</th>
                    <th>Receiver</th>
                    <th>Date Created</th>
                    <th>Date Received</th>
                    <th>Project</th>
                    <th>Vendor</th>
                    <th>Cost</th>
                    <th>Status</th>
                    <th>Delay</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>{{ grn?.id }}</td>
                    <td>{{ grn?.lpo_no }}</td>
                    <td>{{ grn?.requester }}</td>
                    <td>{{ grn?.receiver }}</td>
                    <td>{{ grn?.date }}</td>
                    <td>{{ grn?.received_date }}</td>
                    <td>{{ grn?.project }}</td>
                    <td>{{ grn?.vendor ?? "No vendor" }}</td>
                    <td>{{ grn?.cost }}</td>
                    <td>
                      <span class="badge inv-status" :class="'badge-' + grn?.status?.class">
                        {{ grn?.status?.key }}
                      </span>
                    </td>
                    <td>{{ grn?.delay }}</td>
                    <td>
                      <a
                        v-if="user_permissions.includes('can_print_grn')"
                        href="javascript:void(0);"
                        @click="printGrn(grn, items)"
                        class="text-success me-2"
                      >
                        <i class="bi bi-printer fs-4"></i>
                      </a>
                      <a
                        href="javascript:void(0);"
                        class="text-secondary position-relative me-2"
                        @click.stop="noteModalRef.open(null, grn?.id)"
                      >
                        <i class="bi bi-journal-bookmark-fill fs-4"></i>
                        <span
                          v-if="grn?.logs_count > 0"
                          class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                          style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                        >
                          {{ grn?.logs_count }}
                        </span>
                      </a>
                    </td>
                  </tr>
                  <tr v-if="grn?.briefing != null">
                    <td colspan="5"><b>Brief Description :</b> {{ grn?.briefing }}</td>
                  </tr>
                  <tr v-if="grn?.remarks">
                    <td colspan="5"><b>Remarks :</b> {{ grn?.remarks }}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>

      <div class="row layout-top-spacing">
        <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
          <div class="panel p-0">
            <div  class="custom-table table3 table-responsive">
              <table class="table table-striped table-bordered">
                <thead>
                  <tr>
                    <th>SNo</th>
                    <th>Item</th>
                    <th>Description</th>
                    <th>Vendor</th>
                    <th>Unit</th>
                    <th>Purchased</th>
                    <th>Received</th>
                    <th>Shortage</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(item, index) in items" :key="item.id">
                    <td>{{ index + 1 }}</td>
                    <td>{{ item.item }}</td>
                    <td>{{ item.description }}</td>
                    <td>{{ item.vendor }}</td>
                    <td>{{ item.unit }}</td>
                    <td>{{ item.purchased }}</td>
                    <td>
                      <span v-if="item.returned_quantity > 0">
                        <span class="text-muted text-decoration-line-through">{{ item.purchased }}</span>
                        <span class="text-danger ms-2">Returned: {{ item.returned_quantity }}</span>
                      </span>
                      <span v-else>{{ item.received }}</span>
                    </td>
                    <td>{{ item.shortage }}</td>
                  </tr>
                  <tr v-for="(item, index) in items" :key="'remark-' + item.id">
                    <td
                      colspan="8"
                      class="bg-white text-success"
                      v-if="item.returned_quantity > 0"
                    >
                      <strong>Remark:</strong>
                      <i>Returned Quantity : {{ item.returned_quantity }} @ {{ formatNumber(item.rate) }}</i>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
      </div>
    </div>
</div>

 <NoteModal
      ref="noteModalRef"
      :source-id="grn?.id"
      source="GRN"
      module="GOOD RECEIVED NOTES"
      title="Grn"
      @logs-updated="(count) => { if (grn) grn.logs_count = count }"
    />


  </div>

</template>

<script setup>
import { ref, inject, onMounted, watch } from "vue";
import { useRoute } from "vue-router";
import axios from "axios";
import { useMeta } from "@/composables/use-meta";
import NoteModal from "@/components/reusables/NoteModal.vue";

useMeta({ title: "GRN Preview" });

const route = useRoute();
const noteModalRef = ref(null);

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const printGrn = inject("printGrn");
const showError = inject("showError");
const tableShimmer = inject("tableShimmer");
const formatNumber = inject("formatNumber");
const formatDate = inject("formatDate");

const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;

const loading_spinner = ref(false);
const grn = ref(null);
const items = ref([]);

const mapItems = (approval) => {
  const approvalDate = new Date(approval?.created_at);
  const filterDate = new Date("2025-10-19");

  let itemsList = approval?.items || [];

  if (approvalDate >= filterDate) {
    itemsList = itemsList.filter((item) => item.requisition_items?.vendor_id);
  }

  return itemsList.map((data, index) => {
    const receivedQty = Array.isArray(data.grn_items)
      ? data.grn_items.reduce((sum, gi) => sum + (parseFloat(gi.quantity) || 0), 0)
      : parseFloat(data.grn_item?.quantity) || 0;

    return {
      SNo: index + 1,
      id: data.id,
      unit: data.requisition_items?.units,
      rate: data.requisition_items?.rate ?? 0,
      vendor: data.requisition_items?.vendor?.name ?? "---",
      item: data.requisition_items?.remark,
      description: data.requisition_items?.description,
      purchased: data.quantity ?? 0,
      received: receivedQty,
      shortage: (data.quantity - receivedQty).toFixed(2),
      returned_quantity:
        data.grn_items
          ?.filter((gi) => gi.status_id === 42)
          .reduce((sum, gi) => sum + (parseFloat(gi.quantity) || 0), 0) ?? 0,
    };
  });
};

const grn_id = ref('');

const getGrn = async (id) => {
  loading_spinner.value = true;
  try {
    const { data } = await axiosInstance.get(
      `good-received-notes?grn_id=${id}`
    );

    const record = data?.[0];

    if (!record) {
      grn.value = null;
      return;
    }

    const vendors = [
      ...new Set(
        (record.approval?.items || [])
          .map((item) => item.requisition_items?.vendor?.name)
          .filter(Boolean)
      ),
    ];

    grn.value = {
      ...record,
      briefing: record.approval?.requisition?.description,
      project: record.approval?.requisition?.project?.short_name ?? "no project",
      requester: record.approval?.requester?.name ?? "Unknown",
      lpo_no: "0" + record.approval_list_id,
      receiver: record?.receiver?.name ?? "---",
      vendor: vendors.length > 0 ? vendors.join(", ") : "No vendor",
      date: formatDate(record.created_at),
      received_date: formatDate(record.date),
      status: { key: record.status_key, class: record.status_class },
      delay: record.status_key === "Delayed" ? record.delayed_count : "--",
      cost: formatNumber(
        record.approval.items.reduce(
          (total, i) =>
            total + parseFloat(i.quantity) * parseFloat(i.requisition_items?.rate ?? 0),
          0
        )
      ),
    };

    items.value = mapItems(record.approval);
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    loading_spinner.value = false;
  }
};

const props = defineProps({
    GrnId: String
});

watch(
    () => props.GrnId,
    (newId) => {
        if (newId) {
            getGrn(newId);
        }
    },
    { immediate: true }
);
</script>